document.addEventListener("alpine:init",function(){Alpine.data("product",()=>({activeVariant:null,productVariant:null,submitting:!1,init(){var t=this.$root.querySelector(".variant-on");t&&(this.activeVariant=t.getAttribute("data-option-variant"),this.productVariant=t.getAttribute("data-option-product"))},makeActive:function(t){var a=this.$root.querySelector(".variant-on");a&&(a.classList.remove("variant-on"),a.classList.add("variant-off")),t.target.classList.remove("variant-off"),t.target.classList.add("variant-on"),this.activeVariant=t.target.getAttribute("data-option-variant"),this.productVariant=t.target.getAttribute("data-option-product")},addToCart:function(t){this.submitting=!0,fetch("/prints/cart",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({uri:this.$refs.uri.value,variant:this.activeVariant,action:"add",csrf:this.$refs.csrf.value})}).then(a=>{if(!a.ok)throw new Error("HTTP "+a.status);document.location.replace("cart")}).catch(()=>{this.submitting=!1})}}))});
